        "quote": "是否有发热、伤口红肿热痛/流脓恶臭/变黑、脚部突然更肿"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00074",
        "explanation": "Doctor gives practical, family-friendly instructions for transport, hydration, and medication handling tailored to the caregiver's anxiety and the patient's reluctance.",
        "quote": "路上清醒、能正常吞咽且不恶心呕吐，可以少量多次喝白水，不喝含糖饮料，也不要强迫进食"
      }
    ]
  },
  "dimension_ratings": {
    "actionability_responsibility_chain": "good",
